#!/usr/bin/env bash
# Runs the Python tools (c64/ll2mos.py, c64/wasm2mos.py, dos/wasm2i386.py) and
# their C# port (sdk/ZeroCSharp.Bitcode, "zero-bitcode") on every program
# already built for the C64 and DOS, and fails if any output differs, apart
# from the "Generated by" line. Temporary: it goes with the Python tools.
#
# Usage: scripts/compare-bitcode-tools.sh [BIN]     BIN defaults to ./bin
set -euo pipefail
cd "$(dirname "$0")/.."
bin=${1:-bin}

dotnet build sdk/ZeroCSharp.Bitcode -c Release -o bin/tools/zero-bitcode -v q -nologo > /dev/null
tool=(dotnet bin/tools/zero-bitcode/zero-bitcode.dll)

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
compared=0
failed=0

# Compares two folders' files; .s and .c files without their first line.
same() {
    local a=$1 b=$2 file name
    for file in "$a"/*; do
        name=$(basename "$file")
        if [ ! -f "$b/$name" ]; then
            echo "  only from Python: $name"
            return 1
        fi
        case "$name" in
            *.s|*.c) cmp -s <(tail -n +2 "$file") <(tail -n +2 "$b/$name") || { echo "  differs: $name"; return 1; } ;;
            *)       cmp -s "$file" "$b/$name" || { echo "  differs: $name"; return 1; } ;;
        esac
    done
    for file in "$b"/*; do
        [ -f "$a/$(basename "$file")" ] || { echo "  only from C#: $(basename "$file")"; return 1; }
    done
}

for obj in "$bin"/c64/obj/*/; do
    name=$(basename "$obj")
    [ -f "$obj/$name.bc" ] && compgen -G "$obj/mos/ir/*.ll" > /dev/null || continue
    py=$work/c64-$name-py cs=$work/c64-$name-cs
    mkdir -p "$py" "$cs"
    python3 c64/ll2mos.py "$py" "$obj"/mos/ir/*.ll
    "${tool[@]}" ll2mos "$cs" "$obj"/mos/ir/*.ll
    python3 c64/wasm2mos.py "$obj/$name.bc" "$py/data" "$obj"/mos/ir/*.ll
    "${tool[@]}" wasm2mos "$obj/$name.bc" "$cs/data" "$obj"/mos/ir/*.ll
    if [ -f "$obj/$name.external.o" ]; then
        python3 c64/wasm2mos.py "$obj/$name.external.o" "$py/external" "$obj"/mos/ir/*.ll
        "${tool[@]}" wasm2mos "$obj/$name.external.o" "$cs/external" "$obj"/mos/ir/*.ll
    fi
    compared=$((compared + 1))
    if same "$py" "$cs"; then
        echo "same  c64 $name"
    else
        echo "DIFF  c64 $name"
        failed=$((failed + 1))
    fi
done

for obj in "$bin"/dos/obj/*/; do
    name=$(basename "$obj")
    [ -f "$obj/$name.bc" ] || continue
    py=$work/dos-$name-py cs=$work/dos-$name-cs
    mkdir -p "$py" "$cs"
    python3 dos/wasm2i386.py "$obj/$name.bc" "$py/data"
    "${tool[@]}" wasm2i386 "$obj/$name.bc" "$cs/data"
    if [ -f "$obj/$name.external.o" ]; then
        python3 dos/wasm2i386.py "$obj/$name.external.o" "$py/external"
        "${tool[@]}" wasm2i386 "$obj/$name.external.o" "$cs/external"
    fi
    compared=$((compared + 1))
    if same "$py" "$cs"; then
        echo "same  dos $name"
    else
        echo "DIFF  dos $name"
        failed=$((failed + 1))
    fi
done

echo "$compared programs compared, $failed differ"
[ "$compared" -gt 0 ] && [ "$failed" = 0 ]
